def base_string_uri(uri: str, host: str=None) ->str:
    if not isinstance(uri, str):
        raise ValueError('uri must be a string')
    if len(uri.strip()) == 0:
        raise ValueError('uri must not be empty')

    parsed = urlparse.urlparse(uri)

    scheme = parsed.scheme
    if not scheme:
        raise ValueError('uri must have a scheme')
    scheme = scheme.lower()

    netloc = parsed.netloc

    if host is not None:
        netloc = host

    netloc = netloc.lower() if netloc else netloc

    if not netloc:
        raise ValueError('uri must have a host')

    if netloc.startswith('['):
        bracket_end = netloc.find(']')
        if bracket_end == -1:
            raise ValueError('invalid IPv6 address in uri')
        host_part = netloc[:bracket_end + 1]
        rest = netloc[bracket_end + 1:]
        if rest.startswith(':'):
            port_str = rest[1:]
        else:
            port_str = None
    elif ':' in netloc:
        parts = netloc.rsplit(':', 1)
        host_part = parts[0]
        port_str = parts[1]
    else:
        host_part = netloc
        port_str = None

    if not host_part or host_part == '':
        raise ValueError('uri must have a non-empty host')

    if port_str is not None:
        if port_str == '':
            port_str = None
        else:
            try:
                port_num = int(port_str)
                if port_num <= 0 or port_num > 65535:
                    raise ValueError('invalid port in uri: ' + port_str)
            except ValueError as e:
                if 'invalid port' in str(e):
                    raise
                raise ValueError('invalid port in uri: ' + port_str)

    if port_str is not None:
        port_num = int(port_str)
        if (scheme == 'http' and port_num == 80) or \
           (scheme == 'https' and port_num == 443):
            port_str = None

    if port_str is not None:
        netloc = host_part + ':' + port_str
    else:
        netloc = host_part

    path = parsed.path
    if not path:
        path = '/'

    path = urlparse.quote(urlparse.unquote(path), safe='/-._~!$&\'()*+,;=:@%')

    netloc_encoded = urlparse.quote(urlparse.unquote(netloc), safe='[]-._~!$&\'()*+,;=:@%')

    result = urlparse.urlunparse((scheme, netloc_encoded, path, '', '', ''))
    return result
